def range_sum_bst_brute(root, low, high):
    if not root:
        return 0
    total = root.val if low <= root.val <= high else 0
    return total + range_sum_bst_brute(root.left, low, high) + range_sum_bst_brute(root.right, low, high)  # visit EVERY node

