def range_sum_bst(root, low, high):
    if not root:
        return 0
    if root.val < low:
        return range_sum_bst(root.right, low, high)          # entire left subtree pruned
    if root.val > high:
        return range_sum_bst(root.left, low, high)            # entire right subtree pruned
    return root.val + range_sum_bst(root.left, low, high) + range_sum_bst(root.right, low, high)

