int rangeSumBST(TreeNode* root, int low, int high) {
    if (!root) return 0;
    if (root->val < low) return rangeSumBST(root->right, low, high);        // prune entire left subtree
    if (root->val > high) return rangeSumBST(root->left, low, high);          // prune entire right subtree
    return root->val + rangeSumBST(root->left, low, high) + rangeSumBST(root->right, low, high);
}
